   138→  @Override
   139→  protected Construct getConstructor(Node node) {
   140→    if (pomConstructors.containsKey(node.getType()) && node instanceof ScalarNode) {
   141→      //construct compact form from scalar
   142→      return pomConstructors.get(node.getType());
   143→    } else {
   144→      return super.getConstructor(node);
   145→    }
   146→  }
   147→
   148→  private class ConstructXpp3Dom implements Construct {
   149→    private static final String ATTRIBUTE_PREFIX = "attr/";
   150→
   151→    private Xpp3Dom toDom(Xpp3Dom parent, Map<Object, Object> map) {
   152→
   153→      for (Map.Entry<Object, Object> entry : map.entrySet()) {
   154→        String key = entry.getKey().toString();
   155→        Object entryValue = entry.getValue();
   156→        Xpp3Dom child = new Xpp3Dom(key);
   157→
   158→        if (key.startsWith(ATTRIBUTE_PREFIX)) {
   159→          toAttribute(parent, key.replace(ATTRIBUTE_PREFIX, ""), entryValue);
   160→          continue;
   161→        }
   162→
   163→        // lists need the insertion of intermediate XML DOM nodes which hold the actual values
   164→        if (entryValue instanceof List && !((List) entryValue).isEmpty()) {
   165→          toDom(child, key, (List) entryValue);
   166→        } else if (entryValue instanceof Map) {
   167→          //noinspection unchecked
   168→          child = toDom(child, (Map) entryValue);
   169→        } else { // if not a list or map then copy the string value
   170→          child.setValue(entryValue.toString());
   171→        }
   172→        parent.addChild(child);
   173→      }
   174→      return parent;
   175→    }
   176→
   177→    private void toDom(Xpp3Dom parent, String parentKey, List list) {
   178→      Object firstItem = list.get(0);
   179→
   180→      String childKey;
   181→
   182→      // deal with YAML explicit pairs which are mapped to Object[] by SnakeYAML
   183→      if (firstItem.getClass().isArray()) {
   184→        for (Object item : list) {
   185→          Object[] pair = (Object[]) item;
   186→          childKey = "" + pair[0];
   187→          Xpp3Dom itemNode = new Xpp3Dom(childKey);
   188→          if (pair[1] != null && pair[1] instanceof Map)
   189→            //noinspection unchecked
   190→            toDom(itemNode, (Map) pair[1]);
   191→          else
   192→            itemNode.setValue("" + pair[1]);
   193→          parent.addChild(itemNode);
   194→        }
   195→      } else { // automagically determine the node's child key using the collection node's name
   196→        if (!parentKey.endsWith("s")) {
   197→          throw new RuntimeException(format("collection key '%s' does not end in 's'. Please resort to the " +
   198→              "documentation on how to use explicit pairs for specifying child node names", parentKey));
   199→        }
   200→
   201→        if ("reportPlugins".equals(parentKey)) {
   202→          childKey = "plugin";
   203→        } else {
   204→          childKey = parentKey.substring(0, parentKey.length() - 1);
   205→          if (childKey.endsWith("ie")) {
   206→            childKey = childKey.substring(0, childKey.length() - 2) + "y";
   207→          }
   208→        }
   209→
   210→        for (Object item : list) {
   211→          Xpp3Dom itemNode = new Xpp3Dom(childKey);
   212→          if (item instanceof Map)
   213→            //noinspection unchecked
   214→            toDom(itemNode, (Map) item);
   215→          else
   216→            itemNode.setValue(item.toString());
   217→          parent.addChild(itemNode);
   218→        }
   219→      }
   220→    }
   221→
   222→    private void toAttribute(Xpp3Dom parent, String key, Object value) {
   223→      if (value instanceof List || value instanceof Map) {
   224→        throw new YAMLException("Attribute's value has to be a plain string. Node: " + parent);
   225→      }
   226→
   227→      parent.setAttribute(key, value.toString());
   228→    }
   229→
   230→    public Object construct(Node node) {
   231→      Map<Object, Object> mapping = constructMapping((MappingNode) node);
   232→      Xpp3Dom parent = new Xpp3Dom("configuration");
   233→      return toDom(parent, mapping);
   234→    }
   235→
   236→    public void construct2ndStep(Node node, Object object) {
   237→      throw new YAMLException("Unexpected recursive mapping structure. Node: " + node);
   238→    }
   239→  }
   240→
   241→  class MavenObjectConstruct extends Constructor.ConstructMapping {
   242→    @Override
   243→    protected Object constructJavaBean2ndStep(MappingNode node, Object object) {
   244→      Class<?> type = node.getType();
   245→
   246→      List<Class> specialCases = Arrays.<Class>asList(Dependency.class, Model.class, Plugin.class, ReportPlugin.class);
   247→      List<Class> configurationContainers = Arrays.<Class>asList(Plugin.class, PluginExecution.class,
   248→          ReportPlugin.class, ReportSet.class);
   249→
   250→      if (configurationContainers.contains(type)) {
   251→        for (NodeTuple valueNode : node.getValue()) {
   252→          Node keyNode = valueNode.getKeyNode();
   253→          Node childValueNode = valueNode.getValueNode();
   254→          if (keyNode instanceof ScalarNode && "configuration".equals(((ScalarNode) keyNode).getValue())) {
   255→            childValueNode.setTag(XPP3DOM_TAG);
   256→          }
   257→        }
   258→      }
   259→
   260→      if (specialCases.contains(type)) {
   261→        String coordinate = removeId(node);
   262→        if (coordinate == null) {
   263→          return super.constructJavaBean2ndStep(node, object);
   264→        }
   265→        if (type.equals(Dependency.class)) {
   266→          Dependency dep = (Dependency) super.constructJavaBean2ndStep(node, object);
   267→          return ConstructDependency.createDependency(coordinate, dep);
   268→        } else if (type.equals(Model.class)) {
   269→          Coordinate coord = Coordinate.createCoordinate(coordinate);
   270→          Model model = (Model) super.constructJavaBean2ndStep(node, object);
   271→          return coord.mergeModel(model);
   272→        } else if (type.equals(Plugin.class)) {
   273→          Coordinate coord = Coordinate.createCoordinate(coordinate);
   274→          Plugin plugin = (Plugin) super.constructJavaBean2ndStep(node, object);
   275→          return coord.mergePlugin(plugin);
   276→        } else if (type.equals(ReportPlugin.class)) {
   277→          Coordinate coord = Coordinate.createCoordinate(coordinate);
   278→          ReportPlugin plugin = (ReportPlugin) super.constructJavaBean2ndStep(node, object);
   279→          return coord.mergeReportPlugin(plugin);
   280→        }
   281→      }
   282→      // create JavaBean
   283→      return super.constructJavaBean2ndStep(node, object);
   284→    }
   285→  }
   286→
   287→  /**
   288→   * Dirty hack - remove 'id' if it is present.
   289→   *
   290→   * @param node - the node to remove the coordinate from
   291→   * @return removed coordinate if it was removed
   292→   */
   293→  private String removeId(MappingNode node) {
   294→    NodeTuple id = null;
   295→    String scalar = null;
   296→    for (NodeTuple tuple : node.getValue()) {
   297→      ScalarNode keyNode = (ScalarNode) tuple.getKeyNode();
   298→      String key = keyNode.getValue();
   299→      if ("id".equals(key)) {
   300→        id = tuple;
   301→        ScalarNode valueNode = (ScalarNode) tuple.getValueNode();
   302→        scalar = valueNode.getValue();
   303→      }
   304→    }
   305→    if (id != null) {
   306→      node.getValue().remove(id);
   307→    }
   308→    return scalar;
   309→  }
   310→}
