   148→  private class ConstructXpp3Dom implements Construct {
   149→    private static final String ATTRIBUTE_PREFIX = "attr/";
   150→
   151→    private Xpp3Dom toDom(Xpp3Dom parent, Map<Object, Object> map) {
   152→
   153→      for (Map.Entry<Object, Object> entry : map.entrySet()) {
   154→        String key = entry.getKey().toString();
   155→        Object entryValue = entry.getValue();
   156→        Xpp3Dom child = new Xpp3Dom(key);
   157→
   158→        if (key.startsWith(ATTRIBUTE_PREFIX)) {
   159→          toAttribute(parent, key.replace(ATTRIBUTE_PREFIX, ""), entryValue);
   160→          continue;
   161→        }
   162→
   163→        // lists need the insertion of intermediate XML DOM nodes which hold the actual values
   164→        if (entryValue instanceof List && !((List) entryValue).isEmpty()) {
   165→          toDom(child, key, (List) entryValue);
   166→        } else if (entryValue instanceof Map) {
   167→          //noinspection unchecked
   168→          child = toDom(child, (Map) entryValue);
   169→        } else { // if not a list or map then copy the string value
   170→          child.setValue(entryValue.toString());
   171→        }
   172→        parent.addChild(child);
   173→      }
   174→      return parent;
   175→    }
