   177→    private void toDom(Xpp3Dom parent, String parentKey, List list) {
   178→      Object firstItem = list.get(0);
   179→
   180→      String childKey;
   181→
   182→      // deal with YAML explicit pairs which are mapped to Object[] by SnakeYAML
   183→      if (firstItem.getClass().isArray()) {
   184→        for (Object item : list) {
   185→          Object[] pair = (Object[]) item;
   186→          childKey = "" + pair[0];
   187→          Xpp3Dom itemNode = new Xpp3Dom(childKey);
   188→          if (pair[1] != null && pair[1] instanceof Map)
   189→            //noinspection unchecked
   190→            toDom(itemNode, (Map) pair[1]);
   191→          else
   192→            itemNode.setValue("" + pair[1]);
   193→          parent.addChild(itemNode);
   194→        }
   195→      } else { // automagically determine the node's child key using the collection node's name
   196→        if (!parentKey.endsWith("s")) {
   197→          throw new RuntimeException(format("collection key '%s' does not end in 's'. Please resort to the " +
   198→              "documentation on how to use explicit pairs for specifying child node names", parentKey));
   199→        }
   200→
   201→        if ("reportPlugins".equals(parentKey)) {
   202→          childKey = "plugin";
   203→        } else {
   204→          childKey = parentKey.substring(0, parentKey.length() - 1);
   205→          if (childKey.endsWith("ie")) {
   206→            childKey = childKey.substring(0, childKey.length() - 2) + "y";
   207→          }
   208→        }
   209→
   210→        for (Object item : list) {
   211→          Xpp3Dom itemNode = new Xpp3Dom(childKey);
   212→          if (item instanceof Map)
   213→            //noinspection unchecked
   214→            toDom(itemNode, (Map) item);
   215→          else
   216→            itemNode.setValue(item.toString());
   217→          parent.addChild(itemNode);
   218→        }
   219→      }
   220→    }
