   241→  class MavenObjectConstruct extends Constructor.ConstructMapping {
   242→    @Override
   243→    protected Object constructJavaBean2ndStep(MappingNode node, Object object) {
   244→      Class<?> type = node.getType();
   245→
   246→      List<Class> specialCases = Arrays.<Class>asList(Dependency.class, Model.class, Plugin.class, ReportPlugin.class);
   247→      List<Class> configurationContainers = Arrays.<Class>asList(Plugin.class, PluginExecution.class,
   248→          ReportPlugin.class, ReportSet.class);
   249→
   250→      if (configurationContainers.contains(type)) {
   251→        for (NodeTuple valueNode : node.getValue()) {
   252→          Node keyNode = valueNode.getKeyNode();
   253→          Node childValueNode = valueNode.getValueNode();
   254→          if (keyNode instanceof ScalarNode && "configuration".equals(((ScalarNode) keyNode).getValue())) {
   255→            childValueNode.setTag(XPP3DOM_TAG);
   256→          }
   257→        }
   258→      }
   259→
   260→      if (specialCases.contains(type)) {
   261→        String coordinate = removeId(node);
   262→        if (coordinate == null) {
   263→          return super.constructJavaBean2ndStep(node, object);
   264→        }
   265→        if (type.equals(Dependency.class)) {
   266→          Dependency dep = (Dependency) super.constructJavaBean2ndStep(node, object);
   267→          return ConstructDependency.createDependency(coordinate, dep);
   268→        } else if (type.equals(Model.class)) {
   269→          Coordinate coord = Coordinate.createCoordinate(coordinate);
   270→          Model model = (Model) super.constructJavaBean2ndStep(node, object);
   271→          return coord.mergeModel(model);
   272→        } else if (type.equals(Plugin.class)) {
   273→          Coordinate coord = Coordinate.createCoordinate(coordinate);
   274→          Plugin plugin = (Plugin) super.constructJavaBean2ndStep(node, object);
   275→          return coord.mergePlugin(plugin);
   276→        } else if (type.equals(ReportPlugin.class)) {
   277→          Coordinate coord = Coordinate.createCoordinate(coordinate);
   278→          ReportPlugin plugin = (ReportPlugin) super.constructJavaBean2ndStep(node, object);
   279→          return coord.mergeReportPlugin(plugin);
   280→        }
   281→      }
   282→      // create JavaBean
   283→      return super.constructJavaBean2ndStep(node, object);
   284→    }
   285→  }
